 async function centerPixel(selector='.nw-motion-dialog iframe',gid){return page.$eval(selector,(f,gid)=>{const d=f.contentDocument;f.contentWindow.__NAG_SCROLL_DIRECTOR[gid||d.querySelector('.sc').dataset.id].set(0);const c=d.querySelector('.nw-band-surface');return Array.from(c.getContext('2d').getImageData(Math.floor(c.width/2),Math.floor(c.height/2),1,1).data);},gid);}
