  await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,bg:'#527467',elements:[mkEl('label',{text:'Exterior',name:'Exterior'})]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),outside:sec().elements[0]}));
  await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="'+template+'"]');await ready();assert.equal(await page.$eval('[data-motion-config="duration"]',n=>n.value),'12');assert.equal(await page.$eval('[data-motion-stream-count]',n=>[n.min,n.max].join(',')),'3,12');assert.equal(await page.$eval('[data-motion-stream="cardSize"]',n=>[n.value,n.min,n.max].join(',')),vertical?'34,22,50':'32,22,48');assert.equal(await page.$eval('[data-motion-stream="curve"]',n=>[n.value,n.min,n.max,n.step].join(',')),'70,-100,100,5');assert.equal(await page.$eval('[data-motion-stream="gap"]',n=>[n.value,n.min,n.max,n.step].join(',')),'2.5,1,8,0.5');assert.equal(await page.$eval('[data-motion-stream="cardRatio"]',n=>n.value),'1:1');
