  await change('[data-motion-stream-count]','3',3);await page.click('[data-motion-library-tab="elements"]');await page.click('[data-motion-layer="'+start[0].id+'"]');assert.equal(await page.$eval('[data-motion-element-remove]',n=>n.disabled),true);await change('[data-motion-stream-count]','12',12);await page.click('[data-motion-layer="'+start[0].id+'"]');assert.equal(await page.$eval('[data-motion-duplicate]',n=>n.disabled),true);await change('[data-motion-stream-count]','6');assert.deepEqual((await pose(0)).map(n=>[n.id,n.src]),start.map(n=>[n.id,n.src]));await page.click('[data-motion-layer="'+start[0].id+'"]');assert.equal(await page.$eval('[data-motion-duplicate]',n=>n.disabled),false);
